mapper.select:
/* CastExecutionMapper.retrieveBaseSmltId */
SELECT MAX(SMLT_ID) KEEP (DENSE_RANK LAST ORDER BY TO_NUMBER(SMLT_ID))
FROM PMOWN.TN_PM_SMLT_STNG WHERE EXCN_YMD = #{ymd} AND SMLT_TYPE = 'Auto'

SELECT U.* FROM PMOWN.TN_PM_SMLT_USER_MSTR U WHERE U.PRPT_STNG_RSRC_ID = #{resourceId}
AND REGEXP_LIKE(U.PRPT_STNG_RSRC_ID, '^PS[0-9]{3}$')
AND SUBSTR(U.PRPT_STNG_RSRC_ID, 3) BETWEEN '500' AND '998'
